一个温润如玉，一个平静如水。

只有两个人自己知道，那一眼里，有多少东西在无声地交锋。

散场的时候，人群还在兴奋地议论着这场黑马逆袭。有人不服气，说陈渊赢得蹊跷；有人不服气，说柳风是让着他；更多的人则在盘算，庄家这一回，赔得裤衩都不剩。

