那里，暗金色的胎记正一点一点地亮起来。

洛清欢一把攥住他的手腕。

「你疯了？」她的声音压得极低，却压不住其中的颤抖，「你方才自己也听见了——那老东西说『尊上会亲自来取』。你身上这道胎记，和第七根柱子上那个少年的一模一样。你要是现在把气息放出去，等于是在这三十里地上点了一盏灯。」

「我知道。」

「你知道你还——」

「我知道。」

陈渊重复了一遍，语气很平静。

他把她的手轻轻掰开。

「洛清欢。」

「干嘛。」

「你父亲让你来确认那是不是收割台。」

