「确认了，然后呢？」

洛清欢愣住了。

「回去报信？」

「报给谁？」陈渊问，「中州洛家？青岚宗掌门？还是那些坐在山下等着我们抢完机缘回去领赏的长老？」

他指了指祭坛上那九个人。

「等报信的人回来，他们已经干了。」

洛清欢说不出话。

陈渊把玄铁剑插进土里，蹲下身，用手指在脚边的沙土上画了一个圈。

「我有个法子，」他说，「但需要一个人在外面接应。」

「什么法子？」

「这坛子的血，是从那九根柱子往里流的，对吧？」

「对。」

「那我就从这里，」陈渊在圈上画了一条线，指向祭坛底部，「把血往回抽。」

洛清欢的脸色变了。

「你要吞了整座坛？」

「不是整座，」陈渊说，「是那九道锁链里的血。锁链一空，坛就没了引子。没引子，它开不了。」

