「我吞不了，」陈渊承认，「所以我要你帮个忙。」

他抬起头。

「你那把剑能破魔。等我把血抽出来的一瞬间，坛子会反噬——那一瞬间，坛上的符文会全部亮起来。你在那个时候砍第三层，一剑就够。」

