这一等，就是两个时辰。

子时前后，祭坛下换了一次防。原本那十几个黑袍教徒撤走了一半，换上来一批新的。陈渊屏息数着他们的脚步声、说话声、甲叶碰撞声，把每个人的位置在心里默记了三遍。

换防的时候，他注意到一件事。

那些教徒走路的时候，都在下意识地避开祭坛正东方向的一块空地。

那块空地上什么都没有。

只是一片被踩得极平整的沙土。

「你看那边。」他压低声音，指给洛清欢看。

洛清欢看了一眼，眉头皱了起来。

