「对，」陈渊说，「三十里的盆地，别的地方都长满了那种暗红色的苔，只有那一块是空的，而且踩得比别处都平。」

「说明什么？」

「说明那儿埋着东西，」陈渊说，「而且埋得浅。他们怕踩塌了。」

洛清欢盯着那块空地看了半晌，忽然吸了一口气。

「我想起来了。」

「想起什么？」

「我父亲给我看过那部古籍的摹本，」洛清欢的声音压得极低，「上面画了一张收割台的图。台有九层，九柱，九脉——这些都对得上。」

她抬起手，在沙地上画了一个方框，又在方框的东侧点了一个点。

「但图上，台基的东侧还画了一样东西。」

