陈渊没说话。

他知道这句不能接。接了就落了套。

"陈渊。"

一个声音从堂外传进来。

不高，也不急，甚至带着点笑。

"你辛苦了。"

人群自动往两边让开。

萧景行跨过门槛，白衣胜雪，腰上挂着一块青玉，走得不快，每一步都像踩着节拍。他今日没带剑，双手拢在袖里，进堂先朝三位长老拱手，礼数周全。

"见过三位长老。"

陈平脸色缓和了些。

