那是一座山。

一座由剑堆起来的山。

陈渊站在原野上，仰着头。

他这辈子没见过这么多剑。密集的、层层叠叠的、从地面一直堆到百丈高的，全是剑。

长的，短的，直的，弯的；有的还亮着，有的已经锈成了一团；有的插得笔直，有的歪歪斜斜。十万柄剑挤在一起，剑尖朝着天，剑柄埋在底下，从远处看过去，像一片黑色的、长满刺的海。

山不是死的。

山里在动。

不是风在吹——是有东西在剑与剑之间流动，很慢，很淡，灰白色的一层，缠着整个山体往上爬，爬到一半就散了。

"那是什么？"

