他没追上。

陈渊走进了那片锈地。

奇怪的是，剑冢的边界，没有拦人。

他一路走到剑山脚下，站在那一片层层叠叠的剑跟前。

剑山很高，他站在底下，小得像一粒落进海里的沙。

他抬起头。

灰白色的剑气从剑与剑的缝隙里渗出来，擦过他的脸。

很凉。

陈渊把碑立在了剑山正南的脚下。

碑不高，一人高。他把碑面向外，扶正。

做完这一切，他退后三步，站定。

然后他卷起左边的袖子。

露出那块胎记。

